python3 - <<'PY'
import os,re
def imports(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
for seed,label in [('AlgebraicJacobian.Jacobian','headline'),('AlgebraicJacobian','root')]:
    seen,stack=set(),[seed]
    while stack:
        m=stack.pop()
        if m not in seen: seen.add(m); stack+=imports(m)
    mods={os.path.join(d,f)[:-5].replace('/','.') for d,_,fs in os.walk('AlgebraicJacobian') for f in fs if f.endswith('.lean')}
    print(f'{label}: {len(seen & mods)} of {len(mods)}; unrooted={len(mods-seen) if label=="root" else "n/a"}')
PY

